//
// Browser property specs for the reusable MDX editor layout contracts:
// Property 9 (fixed layout), Property 10 (content layout), Property 11
// (horizontal containment), and Property 12 (lazy stability). These rely on a
// real browser for computed geometry, so they live in Cypress rather than the
// Bun unit suite.

import { visualEditable } from "../support/mdxEditor.js";

const DEMO_PATH = "/components/mdxEditor";

function openDemo() {
  cy.signInAsUser(0);
  cy.visit(DEMO_PATH);
  cy.waitForClerkLoaded();
  cy.get("[data-cy='mdx-editor-demo']", { timeout: 20000 }).should("exist");
}

function openInstagram() {
  cy.signInAsUser(0);
  cy.visit("/instagreg");
  cy.waitForClerkLoaded();
  cy.get("[data-cy='igPosts_list']", { timeout: 20000 }).should("exist");
}

describe("mdx editor layout contracts", () => {
  describe("Property 9: fixed layout (component demo)", () => {
    beforeEach(() => {
      cy.viewport(1280, 900);
      openDemo();
    });

    it("the demo shell uses fixed sizing and does not grow the authoring row", () => {
      cy.get("[data-cy='mdx-editor']", { timeout: 20000 })
        .should("have.attr", "data-sizing", "fixed");

      cy.get(
        "[data-cy='mdx-editor-demo'] section[aria-labelledby='mdx-authoring-heading']",
      )
        .invoke("outerHeight")
        .then((before) => {
          // Typing many lines must not expand the fixed authoring section.
          // Click a visible position: the contenteditable is taller than the
          // fixed-height shell, so its centre is clipped and covered.
          cy.get("[data-cy='mdx-visual-editor']", { timeout: 20000 }).should(
            "exist",
          );
          visualEditable()
            .click("top")
            .type("line{enter}".repeat(40), { delay: 0 });
          cy.get(
            "[data-cy='mdx-editor-demo'] section[aria-labelledby='mdx-authoring-heading']",
          )
            .invoke("outerHeight")
            .then((after) => {
              expect(Math.abs(Number(after) - Number(before))).to.be.lessThan(
                24,
              );
            });
        });
    });
  });

  describe("Property 10: content layout (Instagram create)", () => {
    beforeEach(() => {
      cy.viewport(1280, 900);
      openInstagram();
    });

    it("grows with content and exposes no internal vertical scrollbar", () => {
      cy.get(
        "[data-cy='p_text_content_field'] [data-cy='mdx-editor']",
        { timeout: 20000 },
      ).should("have.attr", "data-sizing", "content");

      cy.get("[data-cy='p_text_content_field'] [data-cy='mdx-editor']")
        .invoke("outerHeight")
        .then((before) => {
          visualEditable("p_text_content_field")
            .click()
            .type("line{enter}".repeat(20), { delay: 0 });

          cy.get("[data-cy='p_text_content_field'] [data-cy='mdx-editor']")
            .invoke("outerHeight")
            .then((after) => {
              expect(Number(after)).to.be.greaterThan(Number(before));
            });

          // The editable surface should not scroll internally in content mode.
          cy.get("[data-cy='p_text_content_field'] [data-cy='mdx-editor']").then(
            ($el) => {
              const el = $el.get(0);
              expect(el.scrollHeight - el.clientHeight).to.be.lessThan(4);
            },
          );
        });
    });
  });

  describe("Property 11: horizontal containment", () => {
    it("the Instagram create page has no horizontal overflow at 320px", () => {
      cy.viewport(320, 800);
      openInstagram();
      cy.get("[data-cy='p_text_content_field'] [data-cy='mdx-editor']", {
        timeout: 20000,
      }).should("exist");
      cy.document().then((doc) => {
        expect(doc.documentElement.scrollWidth).to.be.lessThan(
          doc.documentElement.clientWidth + 3,
        );
      });
    });

    it("the component demo has no horizontal overflow at 320px", () => {
      cy.viewport(320, 800);
      openDemo();
      cy.document().then((doc) => {
        expect(doc.documentElement.scrollWidth).to.be.lessThan(
          doc.documentElement.clientWidth + 3,
        );
      });
    });
  });

  describe("Property 12: lazy stability", () => {
    beforeEach(() => {
      cy.viewport(1280, 900);
      openDemo();
    });

    it("switching modes preserves the shell inline and block size", () => {
      cy.get("[data-cy='mdx-editor']", { timeout: 20000 }).should("exist");
      cy.get("[data-cy='mdx-editor']")
        .then(($el) => {
          const rect = $el.get(0).getBoundingClientRect();
          return { width: rect.width, height: rect.height };
        })
        .then((before) => {
          cy.get("[data-cy='mdx-vim-toggle']").click();
          cy.get("[data-cy='mdx-vim-editor']", { timeout: 20000 }).should(
            "exist",
          );
          cy.get("[data-cy='mdx-editor']").then(($el) => {
            const rect = $el.get(0).getBoundingClientRect();
            expect(Math.abs(rect.width - before.width)).to.be.lessThan(2);
            expect(Math.abs(rect.height - before.height)).to.be.lessThan(2);
          });
        });
    });
  });

  // Feature: mdx-editor-ui-refinements, Requirement 2 — the DDrvList edit-state
  // editor fills the full available width of its container.
  describe("Requirement 2: DDrvList edit-state editor fills container width", () => {
    function ownerId() {
      return cy
        .env<{ test_users: [Cypress.TestUser, Cypress.TestUser] }>([
          "test_users",
        ])
        .then(({ test_users }) => {
          const owner = test_users[0];
          if (!owner) {
            throw new Error("test_users[0] is missing");
          }
          return owner.user_id;
        });
    }

    beforeEach(() => {
      cy.viewport(1280, 900);
    });

    it("the edit editor's width matches its container's content width", () => {
      cy.uniqueRecordName("post").then((postText) => {
        ownerId().then((identifier) => {
          cy.task("createIgPostAsUser", {
            identifier,
            p_text_content: postText,
            p_public: true,
          });
        });

        cy.signInAsUser(0);
        cy.visit("/instagreg");
        cy.waitForClerkLoaded();

        cy.contains("[data-cy='igPosts_list'] article", postText, {
          timeout: 20000,
        })
          .find("[data-cy='ig_post_actions']")
          .click();
        cy.get("[data-cy='ig_post_edit']").click();

        cy.get(
          "[data-cy='edit_p_text_content_field'] [data-cy='mdx-editor']",
          { timeout: 20000 },
        ).should("exist");

        // The editor shell fills the field wrapper's content box (its width
        // equals the wrapper's client width minus horizontal padding).
        cy.get("[data-cy='edit_p_text_content_field']").then(($field) => {
          const field = $field.get(0);
          const style = window.getComputedStyle(field);
          const padX =
            parseFloat(style.paddingLeft) + parseFloat(style.paddingRight);
          const contentWidth = field.clientWidth - padX;
          cy.get(
            "[data-cy='edit_p_text_content_field'] [data-cy='mdx-editor']",
          ).then(($editor) => {
            const editorWidth = $editor.get(0).getBoundingClientRect().width;
            expect(Math.abs(editorWidth - contentWidth)).to.be.lessThan(2);
          });
        });
      });
    });
  });
});
